"""Complete respiratory failure with eighteen ARDS questions."""
from create_respiratory_failure import rows,q,NV,OX,NS
from qbank_authoring import ref,finalize
GD=ref('Global Consensus: A New Global Definition of ARDS','https://pmc.ncbi.nlm.nih.gov/articles/PMC10870872/')
AR=ref('ATS: Update on Management of Adult ARDS, 2024','https://pmc.ncbi.nlm.nih.gov/articles/PMC10870893/')
LO=ref('ARDSNet: Lower versus Traditional Tidal Volumes','https://www.nejm.org/doi/full/10.1056/NEJM200005043421801')
PO=ref('PROSEVA: Prone Positioning in Severe ARDS','https://www.nejm.org/doi/full/10.1056/NEJMoa1214103')
FL=ref('FACTT: Fluid-Management Strategies in Acute Lung Injury','https://www.nejm.org/doi/full/10.1056/NEJMoa062200')
q('After sepsis, a patient develops acute hypoxemia and bilateral opacities not primarily explained by cardiac failure or fluid overload. Which syndrome is most consistent?', 'Acute respiratory distress syndrome',[
 ('An isolated pleural effusion as the full explanation','The described bilateral parenchymal process requires a different assessment.'),('Chronic stable pulmonary fibrosis alone','The acute temporal relationship argues for a superimposed acute injury.'),('Cardiogenic edema proven solely by bilateral opacities','Bilateral opacities are not specific to a cardiac cause.')],
 'ARDS is an acute inflammatory lung-injury syndrome', '**A predisposing insult, acute onset, bilateral opacities and impaired oxygenation define the framework.**',['Assess whether cardiac failure or fluid overload predominantly explains the findings.','Imaging and oxygen-support requirements must be interpreted within the chosen definition.'], '**Treat the precipitating cause while limiting further lung injury.**',['Sepsis, pneumonia, aspiration and other insults can trigger it.','ARDS and cardiac dysfunction can coexist.'],[['Timing','Acute onset after an insult'],['Imaging','Bilateral opacities'],['Mechanism','Not primarily cardiogenic or overload']],[GD],style='clinical_scenario')
q('Which feature is added by the newer global ARDS definition compared with an exclusively intubation-based view?', 'An appropriate nonintubated category that can include high-flow nasal oxygen at flows of at least 30 L/min',[
 ('Every patient with dyspnea is classified as ARDS','The remaining syndrome criteria still apply.'),('Bilateral imaging abnormalities are no longer relevant','They remain part of the framework.'),('Heart failure must be the primary cause','The syndrome is not primarily explained by cardiogenic edema.')],
 'ARDS can be recognized before invasive ventilation', '**The global definition includes selected nonintubated patients.**',['Oxygenation thresholds and support conditions remain specified.','It also addresses resource-limited settings and imaging alternatives.'], '**Name the definition when testing a threshold.**',['Berlin and global frameworks are related but not identical.','A new definition does not remove clinical judgment about respiratory support.'],[['Global framework','Includes nonintubated ARDS'],['HFNO','At least 30 L/min in the relevant category'],['Other criteria','Still required']],[GD])
q('An intubated ARDS patient has PaO2 80 mmHg on FiO2 0.80 and PEEP 8 cm H2O. Under Berlin oxygenation severity categories, which grade is present?', 'Severe ARDS',[
 ('Mild ARDS','Mild corresponds to a ratio above 200 up to 300.'),('Moderate ARDS','Moderate is above 100 up to 200; this ratio is exactly 100.'),('No ARDS because PaO2 is 80','The ratio and support context, not PaO2 alone, classify oxygenation impairment.')],
 'Calculate the ratio using FiO2 as a fraction', '**80 / 0.80 = 100 mmHg.**',['At PEEP at least 5, a ratio at most 100 meets the severe Berlin oxygenation category.','The other ARDS criteria must also be present.'], '**Use severity to guide evidence-based support.**',['Optimize lung-protective ventilation.','Assess prone positioning and other escalation according to the full clinical situation.'],[['Mild','200 < ratio ≤300'],['Moderate','100 < ratio ≤200'],['Severe','Ratio ≤100']],[GD,AR],style='clinical_scenario')
q('Why is low tidal volume ventilation beneficial in ARDS?', 'It limits overdistension of the relatively small aerated lung and reduces ventilator-induced injury',[
 ('It guarantees normal PaCO2 without changing respiratory rate','CO2 may rise and minute ventilation requires assessment.'),('It recruits every collapsed alveolus by tidal volume alone','Recruitment depends on pressure, recruitability and other factors.'),('It permits unlimited plateau pressure','Pressure limitation remains central.')],
 'The injured lung is not uniformly available for ventilation', '**A large breath can overdistend the remaining aerated units.**',['Use a lung-protective strategy based on predicted body weight.','Monitor plateau pressure and overall mechanics.'], '**Balance gas exchange with protection.**',['A degree of hypercapnia may be tolerated when appropriate.','Severe acidosis and contraindications need individualized management.'],[['Large tidal volume','Overdistension risk'],['Protective strategy','Smaller volume and pressure limitation'],['Goal','Reduce secondary mechanical injury']],[LO,AR])
q('For a patient with predicted body weight 60 kg, what is a typical initial 6 mL/kg tidal volume target in an ARDS lung-protective strategy?', '360 mL',[
 ('600 mL','This corresponds to 10 mL/kg.'),('720 mL','This corresponds to 12 mL/kg.'),('A value based solely on actual obese body weight','Predicted, not actual, body weight is used for this purpose.')],
 'Use predicted body weight to estimate lung size', '**60 × 6 = 360 mL.**',['Height and sex-based prediction are used rather than adipose mass.','Titrate within the protective strategy according to pressures and gas exchange.'], '**Monitor the delivered breath and patient interaction.**',['Double triggering can increase effective delivered volume.','Do not assume a displayed target guarantees safe lung stress.'],[['PBW','60 kg'],['Dose','6 mL/kg'],['Initial target','360 mL']],[LO])
q('Which pressure is conventionally limited to about 30 cm H2O in ARDS lung-protective ventilation?', 'Plateau pressure',[
 ('Peak pressure regardless of airway resistance','Peak pressure includes a resistive component and is not identical to plateau.'),('Arterial systolic pressure','This is a circulatory rather than airway-pressure measure.'),('Central venous pressure','This does not measure the relevant respiratory plateau.')],
 'Separate resistance from end-inspiratory static pressure', '**Plateau is measured during an appropriate inspiratory pause under suitable conditions.**',['It reflects respiratory-system pressure after flow stops.','Patient effort and chest-wall mechanics affect interpretation.'], '**Respond to excessive pressure with a protective review.**',['Assess tidal volume, PEEP, compliance and patient synchrony.','Do not simply accept a high pressure to normalize every blood gas.'],[['Peak','Includes resistive pressure'],['Plateau','End-inspiratory static estimate'],['Conventional target','At most about 30 cm H2O']],[LO,AR])
q('Peak inspiratory pressure suddenly rises but plateau pressure is unchanged in a passively ventilated patient. Which mechanism best fits?', 'Increased airway resistance, such as tube obstruction or bronchospasm',[
 ('A large isolated fall in static compliance as the sole explanation','This generally raises plateau pressure as well.'),('A required increase in lung recruitment','The pressure pattern does not establish that.'),('Improved airway caliber','That would not explain increased resistive pressure.')],
 'The peak–plateau difference reflects a resistive component', '**An unchanged plateau with a higher peak points toward increased resistance.**',['Check the tube, secretions, circuit and bronchospasm.','Compare flow and pressure conditions when interpreting the change.'], '**Assess the patient urgently rather than only changing alarm limits.**',['Severe obstruction can impair ventilation.','Multiple mechanical problems can coexist.'],[['High peak, stable plateau','Resistance concern'],['High peak and plateau','Compliance or volume/pressure problem possible'],['Immediate review','Tube, circuit and airway']],[NV,LO],style='clinical_scenario')
q('In a passive ventilated patient, plateau pressure is 28 and total PEEP is 12 cm H2O. What is the driving pressure?', '16 cm H2O',[
 ('40 cm H2O','That adds rather than subtracts the pressures.'),('28 cm H2O','That ignores the baseline pressure.'),('12 cm H2O','That is the stated PEEP, not the pressure difference.')],
 'Driving pressure is a difference across the tidal breath', '**Driving pressure is plateau pressure minus total PEEP under suitable measurement conditions.**',['28 − 12 = 16.','Interpret it with compliance, tidal volume and patient effort.'], '**Use it as a physiological marker within a protective strategy.**',['It is not a substitute for the full ventilation plan.','Measurement during active effort can be misleading.'],[['Plateau','28'],['Total PEEP','12'],['Difference','16 cm H2O']],[AR,LO])
q('An intubated patient with ARDS has PaO2/FiO2 110 despite optimized protective ventilation. Which intervention has strong trial support when performed by a trained team?', 'Early prolonged prone positioning',[
 ('Routine high-frequency oscillation as first-line replacement','This is not the evidence-supported routine strategy.'),('Increasing tidal volume to 12 mL/kg to normalize the ratio','This risks additional lung injury.'),('Brief turning for 5 minutes as equivalent to the studied intervention','The benefit evidence involves prolonged sessions.')],
 'Proning is more than a transient oxygenation maneuver', '**PROSEVA used sessions of at least 16 hours in severe hypoxemic ARDS.**',['The population had PaO2/FiO2 below 150 under specified support conditions.','Protective ventilation remained part of care.'], '**Use a trained team and a safety protocol.**',['Secure the airway and lines and protect pressure areas.','Assess contraindications and hemodynamic tolerance.'],[['Population','Severe hypoxemia despite protective support'],['Session','Prolonged, about 16 hours or more in PROSEVA'],['Purpose','Improve outcomes, not only a display value']],[PO,AR],style='clinical_scenario')
q('What is the 2024 ATS recommendation regarding prolonged lung recruitment maneuvers in moderate-to-severe ARDS?', 'Recommend against their use',[
 ('Mandate prolonged recruitment maneuvers before every PEEP adjustment','That is contrary to the updated recommendation.'),('Replace low tidal volume ventilation with recruitment alone','Recruitment is not a substitute for lung protection.'),('Use sustained very high pressures without hemodynamic monitoring','This can produce serious harm.')],
 'Recruitability does not make every high-pressure maneuver safe', '**Prolonged recruitment maneuvers can cause hemodynamic and pulmonary harm.**',['The guideline distinguishes higher PEEP from adding prolonged recruitment maneuvers.','Patient-specific mechanics and circulation remain important.'], '**Titrate ventilation with a protective goal.**',['Avoid overdistension and excessive pressure exposure.','Reassess oxygenation and RV/circulatory effects after changes.'],[['Prolonged recruitment','Recommended against'],['Higher PEEP','Separate conditional strategy'],['Monitoring','Lung mechanics and hemodynamics']],[AR])
q('Under the 2024 ATS guideline, which PEEP approach is conditionally suggested in moderate-to-severe ARDS?', 'Higher PEEP without prolonged lung recruitment maneuvers, individualized to response',[
 ('Zero PEEP in every patient','This is not the recommended universal strategy.'),('The highest possible PEEP regardless of hypotension or overdistension','Higher is not automatically better without physiological reassessment.'),('Higher PEEP only if combined with a prolonged recruitment maneuver','The recommendation specifically separates the two.')],
 'PEEP can reduce cyclic collapse but can also overdistend or impair circulation', '**Use a studied strategy with assessment of benefit and harm.**',['More recruitable lungs may respond differently from poorly recruitable lungs.','Oxygenation improvement alone does not establish overall safety.'], '**Monitor pressures, compliance and perfusion.**',['Reduce or modify the approach if adverse effects dominate.','Integrate proning and other proven measures rather than escalating one setting indefinitely.'],[['Potential benefit','Reduced derecruitment'],['Potential harm','Overdistension and circulatory effects'],['Guideline','Conditional higher PEEP without prolonged recruitment']],[AR])
q('Which statement accurately reflects the 2024 ATS ARDS guideline on corticosteroids?', 'They are conditionally suggested for adult ARDS, with patient and regimen considerations',[
 ('They are an unconditional requirement in every patient at any stage','The recommendation is conditional and clinical context matters.'),('A single universal drug, dose and duration is definitively established for every ARDS cause','The evidence does not establish that universal regimen.'),('They replace treatment of the precipitating infection','They are not a substitute for cause-directed care.')],
 'Name the guideline and preserve the conditional nature of the recommendation', '**ATS suggests corticosteroids for adult ARDS.**',['Potential benefit must be weighed against hyperglycemia, infection and other adverse effects.','Etiology, timing and coexisting conditions can alter the decision.'], '**Continue the full ARDS treatment bundle.**',['Protective ventilation and indicated proning remain essential.','Do not generalize an ARDS recommendation to every patient with hypoxemia.'],[['Recommendation','Conditional suggestion'],['Regimen','Requires context-specific selection'],['Parallel treatment','Cause control and protective support']],[AR])
q('Which is the best interpretation of the 2024 ATS recommendation on neuromuscular blockade in ARDS?', 'A conditional option in early severe ARDS rather than routine prolonged paralysis for all patients',[
 ('Every ventilated patient requires weeks of paralysis','This is neither the scope nor the duration of the recommendation.'),('Paralysis provides analgesia and amnesia by itself','Adequate sedation and analgesia remain necessary.'),('It permits abandonment of lung-protective ventilation','Its use should support, not replace, a protective strategy.')],
 'Use paralysis for a defined clinical objective', '**Selected early severe ARDS may benefit when synchrony and protection are difficult.**',['Balance this against weakness and other harms.','Assess the need daily and limit exposure.'], '**Ensure safe sedation and monitoring.**',['A paralyzed patient cannot express distress normally.','Continue pressure, volume and oxygenation assessment.'],[['Selection','Early severe ARDS'],['Goal','Facilitate appropriate support'],['Safety','Sedation, monitoring and limited duration']],[AR])
q('In ARDS after shock has resolved and perfusion is adequate, which fluid principle is supported by FACTT?', 'A conservative fluid strategy can improve ventilator-free and ICU-free days',[
 ('It proved a significant mortality reduction from withholding all fluid during shock','FACTT did not establish that conclusion or strategy.'),('Large positive fluid balance is required regardless of congestion','Excess fluid can worsen pulmonary edema.'),('Diuresis should override every sign of hypoperfusion','Resuscitation and perfusion safety remain essential.')],
 'Distinguish resuscitation from the later fluid-management phase', '**After stabilization, avoiding unnecessary fluid accumulation can aid pulmonary recovery.**',['FACTT improved ventilator-free and ICU-free days.','The trial did not show a significant primary mortality difference.'], '**Assess circulation, kidney function and response.**',['Do not apply deresuscitation indiscriminately during active shock.','Individualize diuretic and fluid decisions.'],[['Active shock','Restore adequate perfusion'],['After stabilization','Avoid unnecessary fluid accumulation'],['FACTT benefit','More ventilator-free days, not proven mortality benefit']],[FL])
q('A patient with potentially reversible severe ARDS remains profoundly hypoxemic despite protective ventilation and proning. What is an appropriate escalation principle?', 'Early consultation with an experienced VV-ECMO center for selected-patient assessment',[
 ('ECMO is indicated for every patient with mild ARDS','It is a resource-intensive selected rescue/support strategy.'),('Wait for prolonged irreversible multiorgan failure before referral','Late referral can reduce suitability and options.'),('VV-ECMO directly cures the precipitating pneumonia','It supports gas exchange while the underlying disease is treated.')],
 'ECMO selection depends on reversibility, severity and competing risks', '**ATS conditionally suggests VV-ECMO in selected severe ARDS.**',['Assess duration and intensity of prior ventilation.','Bleeding, neurologic and overall prognosis considerations matter.'], '**Use an experienced multidisciplinary pathway.**',['Continue cause-directed and lung-protective care.','Referral for assessment does not imply automatic cannulation.'],[['Indication','Selected refractory severe ARDS'],['Function','Gas-exchange support'],['Decision','Expert assessment of benefit and harm']],[AR],style='clinical_scenario')
q('Why is inhaled nitric oxide not a routine outcome-improving treatment for every ARDS patient?', 'It may transiently improve oxygenation without an established routine survival benefit and has potential harms',[
 ('It never changes pulmonary vascular tone','It is a selective pulmonary vasodilator.'),('Any rise in PaO2 proves improved long-term survival','A physiological response is not equivalent to a patient-centered outcome.'),('It replaces prone positioning and low tidal volumes','It does not replace those evidence-based measures.')],
 'Separate rescue physiology from proven routine benefit', '**A transient oxygenation improvement can be useful as a bridge in selected circumstances.**',['It may be considered when severe hypoxemia or RV dysfunction is being managed.','Routine use has not established a survival advantage.'], '**Continue definitive supportive measures and reassess need.**',['Avoid letting a temporary response delay appropriate escalation.','Monitor relevant toxicity and organ effects.'],[['Immediate effect','May improve oxygenation'],['Evidence limit','No established routine survival benefit'],['Role','Selected bridge rather than universal therapy']],[AR])
q('Why may permissive hypercapnia be accepted during protective ARDS ventilation?', 'Avoiding injurious volume and pressure may take priority over normalizing PaCO2 when the overall physiology permits',[
 ('Any degree of acidosis is harmless in every patient','Severe acidosis and specific comorbidities can be dangerous.'),('It means CO2 and pH no longer need monitoring','Both remain important.'),('It requires deliberate reduction of oxygenation to unsafe levels','The principle concerns ventilation protection, not acceptance of uncontrolled hypoxemia.')],
 'Gas targets must be balanced against mechanical injury', '**A moderately elevated CO2 can accompany a protective tidal-volume strategy.**',['Adjust respiratory rate and other settings within safe limits.','Avoid excessive dynamic hyperinflation or mechanical power.'], '**Consider contraindications and the whole patient.**',['Intracranial pathology and severe RV or circulatory problems can change tolerance.','Reassess pH, hemodynamics and available support options.'],[['Priority','Limit injurious mechanical exposure'],['Trade-off','Some CO2 elevation may be tolerated'],['Limit','Patient-specific acid-base and organ safety']],[LO,AR])
q('After surviving ARDS, a patient has persistent weakness, exercise limitation and psychological distress. Which follow-up principle is most appropriate?', 'Assess multidimensional recovery and rehabilitation needs rather than relying only on a cleared chest radiograph',[
 ('Normal imaging guarantees full recovery','Functional and psychological impairment can persist.'),('Exercise is permanently contraindicated after every ARDS episode','Rehabilitation can be appropriate after assessment.'),('Respiratory follow-up should ignore cognition and mood','Post-critical-illness effects extend beyond lung mechanics.')],
 'Survival is followed by a recovery phase', '**Critical illness can affect muscle function, cognition and mental health.**',['Persistent pulmonary impairment may coexist.','Caregiver and social support needs can influence recovery.'], '**Provide individualized rehabilitation and follow-up.**',['Assess oxygenation and exercise capacity where indicated.','Connect the patient with relevant physical and psychological support.'],[['Pulmonary','Gas exchange and mechanics'],['Physical','Weakness and activity limitation'],['Psychological','Mood, cognition and trauma-related symptoms']],[AR])

if __name__=='__main__':finalize('Respiratory system',8,'Respiratory Failure and ARDS','resp-failure',rows,36)
